// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2006, "8-9", [{"author":"Е. Вельмезова","question":"Жан, Мишель, Даниэль и Фредерик — французские дети, знакомые Бориса. Перед Новым годом Борис послал поздравительные открытки Жану, Мишель, Даниэлю и Фредерик. Скольким девочкам Борис послал открытки?","choices":["ни одной","одной","двум","трём","четырём."],"key":"В","review":["Кому пришли открытки","Французские имена Мишель и Фредерик могут принадлежать и мальчикам, и девочкам. После «послал» требуется дательный падеж.","Мужские имена на согласную изменились: Жан → Жану, Даниэль → Даниэлю. Два других имени остались в исходной форме, как и полагается женским иностранным именам на согласную."]},{"author":"Е. Муравенко","question":"В какой из данных пар слова связаны между собой не так, как в остальных парах?","choices":["<em>мост — мостик</em>","<em>шарф — шарфик</em>","<em>брат — братик</em>","<em>граф — график</em>","<em>гном — гномик</em>."],"key":"Г","review":["Мост и график","Мостик, шарфик, братик и гномик — уменьшительные формы слов мост, шарф, брат и гном.","График в значении «диаграмма» или «расписание» графом в уменьшительной форме не является. Вариант Г образует пару с другим смысловым отношением."]},{"author":"Л. Фёдорова","question":"Какой из грибов назван не по тому принципу, что все остальные?","choices":["<em>подберёзовик</em>","<em>подосиновик</em>","<em>моховик</em>","<em>маслёнок</em>","<em>опёнок</em>."],"key":"Г","review":["По названию гриба","Подберёзовик растёт под берёзами, подосиновик — под осинами, моховик можно встретить во мху, а опёнок часто растёт на пнях.","Маслёнок получил название по маслянистой, скользкой шляпке. В этом названии отразился внешний вид гриба."]},{"author":"Л. Фёдорова","question":"Как правильно?","choices":["<em>междоусобица</em>","<em>междуусобица</em>","<em>междусобица</em>","<em>межусобица</em>","<em>межеусобица</em>."],"key":"А","review":["Ссора между своими","Подберите к слову прилагательное «междоусобный». Оно обозначает столкновение внутри страны или одной группы.","Начало «междо-» сохраняется в существительном «междоусобица». Оно есть и в слове «междоусобие»."]},{"author":"Л. Фёдорова","question":"Какое из слов не может обозначать отсылку к прошлому?","choices":["<em>прежде</em>","<em>раньше</em>","<em>встарь</em>","<em>впредь</em>","все слова могут обозначать отсылку к прошлому."],"key":"Г","review":["Когда наступит «впредь»","Прежде, раньше и встарь можно сказать о том, что уже происходило: «Прежде здесь стоял дом».","«Впредь» значит «с этого момента и в дальнейшем». Например, «Впредь будь осторожнее» обращено к будущему."]},{"author":"Б. Иомдин","question":"Какое из этих слов имеет ударение на <em>и</em>?","choices":["<em>бравировать</em>","<em>гравировать</em>","<em>гримировать</em>","<em>сервировать</em>","<em>формировать</em>."],"key":"А","review":["Где ударение","Произнесите слова целиком: гравирова́ть, гримирова́ть, сервирова́ть, формирова́ть. В них ударение ставится на а.","В слове брави́ровать ударна буква и. Этим оно отличается от четырёх остальных."]},{"author":"С. Бурлак","question":"Даны первые части сложных слов: <em>бацилло-, водо-, книго-, ордено-</em>. В каком порядке следует расположить вторые части, чтобы получились четыре правильных русских слова?","choices":["-<em>носец, -нос, -ноша, -носитель</em>","-<em>носитель, -нос, -ноша, -носец</em>","-<em>носец, -ноша, -нос, -носитель</em>","-<em>носитель, -носец, -ноша, -нос</em>","-<em>нос, -ноша, -носитель, -носец</em>."],"key":"Б","review":["Кто что носит","Тот, кто носит бациллы, — бациллоноситель, а тот, кто носит воду, — водонос.","Переносчика книг называют книгоношей, обладателя ордена — орденоносцем. Получаем «-носитель, -нос, -ноша, -носец»."]},{"author":"О. Шеманаева","question":"Даны названия языков с пропущенными буквами. В каком из них пропущены не те буквы, что во всех остальных?","choices":["<em>неме…ий</em>","<em>туре…ий</em>","<em>шве…ий</em>","<em>калмы…ий</em>","<em>слова…ий</em>."],"key":"В","review":["Согласные в названиях языков","В словах немецкий, турецкий, калмыцкий и словацкий перед «ий» стоят две согласные: цк.","Название шведский сохраняет д из слова «швед», а суффикс начинается с с: шве-дск-ий. Здесь пропущены дск."]},{"author":"О. Шеманаева","question":"Как обычно не говорят о человеке?","choices":["<em>хилый</em>","<em>вялый</em>","<em>сутулый</em>","<em>квёлый</em>","<em>жухлый</em>."],"key":"Д","review":["Какое слово описывает листья","Хилым, вялым, сутулым или квёлым можно назвать человека. Например, квёлый человек выглядит нездоровым и слабым.","«Жухлый» говорят о поблёкшей, вянущей траве или листве. Это прилагательное отличается от остальных обычным употреблением."]},{"author":"Е. Муравенко","question":"В ребусах зашифрованы названия городов, в которых есть победители «Медвежонка». Расшифруйте и расположите по алфавиту эти названия. Какое оказалось в середине списка?","choices":["[САМАРА]","[ОМСК]","[САРАНСК]","[ТЮМЕНЬ]","[НОРИЛЬСК]."],"key":"А","review":["Города по алфавиту","Запятые отбрасывают буквы с начала или конца слова. В А оса теряет о, а марка — к: са + мара. В Б дом без д и сук без у дают Омск. В В из косы, рака и носков получается са + ра + нск.","В Г том с ю вместо о и пень без п дают Тюмень. В Д ножи с р вместо ж, ель без е и сок без о дают Норильск. Список по алфавиту: Норильск, Омск, Самара, Саранск, Тюмень. Третья — Самара."],"figure":{"onlyPictures":true,"options":[{"src":"assets/medvezhonok/2006/8-9-10-1.svg","description":"Слева направо: запятая перед осой, затем почтовая марка, над которой зачёркнута К.","pixelWidth":199,"pixelHeight":110},{"src":"assets/medvezhonok/2006/8-9-10-2.svg","description":"Слева направо: запятая перед домом, затем сучок, над которым зачёркнута У.","pixelWidth":235,"pixelHeight":131},{"src":"assets/medvezhonok/2006/8-9-10-3.svg","description":"Слева направо: две запятые перед косой, рак с запятой после него, носки с запятой после них и зачёркнутой О сверху.","pixelWidth":343,"pixelHeight":129},{"src":"assets/medvezhonok/2006/8-9-10-4.svg","description":"У книги надпись О → Ю, затем запятая и пень.","pixelWidth":235,"pixelHeight":142},{"src":"assets/medvezhonok/2006/8-9-10-5.svg","description":"Слева направо: ножи с надписью Ж → Р, запятая перед елью, пакет сока с зачёркнутой О сверху.","pixelWidth":390,"pixelHeight":149}]}},{"author":"О. Шеманаева","question":"<em>Ты скажешь: ветр..ая Геба,\nКормя Зевесова орла,\nГромокипящий кубок с неба\nСмеясь, на землю пролила.</em>\n(Ф. Тютчев)\nКакое буквосочетание пропущено в этом стихотворном отрывке?","choices":["-<em>ен</em>-","-<em>ян</em>-","-<em>енн</em>-","-<em>ов</em>-","-<em>янн</em>-."],"key":"А","review":["Ветреная Геба","Подставим буквосочетания и сравним их со словарной формой прилагательного «ветреный». Оно пишется с одним н.","В строке нужна форма женского рода «ветреная». Пропущено -ен-."]},{"author":"И. Иткин","question":"Как мы называем бойкого, шумного человека, который ведёт себя развязно, в грубоватой манере?","choices":["<em>разбитый малый</em>","<em>разбитной малый</em>","<em>разбивной малый</em>","<em>разбойный малый</em>","<em>разборный малый</em>."],"key":"Б","review":["Разбитной малый","Бойкого человека, который ведёт себя развязно, в разговорной речи называют «разбитным».","Готовое сочетание — «разбитной малый». Например, «разбитый» скорее обозначил бы человека, который устал или подавлен."]},{"author":"И. Рубанов","question":"Как правильно?","choices":["<em>мы рассмотрели все четыре возможные типы случаев</em>","<em>мы рассмотрели все четыре возможных типов случаев</em>","<em>мы рассмотрели всех четырёх возможных типов случаев</em>","<em>мы рассмотрели все четыре возможных типа случаев</em>","<em>мы рассмотрели всех четыре возможных типов случаев</em>."],"key":"Г","review":["Все четыре типа","«Тип» — неодушевлённое существительное. В выражении «рассмотрели все четыре» винительный падеж совпадает с именительным.","После «четыре» берём «типа», а определение ставим в форме «возможных»: «мы рассмотрели все четыре возможных типа случаев»."]},{"author":"И. Рубанов","question":"Журналист написал о штангисте:\n«<em>Наш земляк победил благодаря своей недюжей силе</em>».\nА как надо было написать?","choices":["так и надо было","<em>наш земляк победил благодаря своей не дюжей силе</em>","<em>наш земляк победил благодаря своей дюжей силе</em>","<em>наш земляк победил благодаря своей дюжинной силе</em>","<em>наш земляк победил благодаря своей недюжинной силе</em>."],"key":"Д","review":["Недюжинная сила","По смыслу журналист говорит об исключительной, необыкновенной силе спортсмена. Такое значение есть у прилагательного «недюжинный».","«Дюжий» значит «крепкий, сильный». Здесь нужно устойчивое сочетание «благодаря своей недюжинной силе»."]},{"author":"П. Аркадьев","question":"Как правильно назвать того, кто плетёт интриги?","choices":["<em>интригист</em>","<em>интригант</em>","<em>интригун</em>","<em>интриган</em>","<em>интрижист</em>."],"key":"Г","review":["Тот, кто плетёт интриги","У слова «интрига» есть словарное название человека, который ведёт интриги или строит козни.","Это «интриган», без т на конце."]},{"author":"А. Бердичевский","question":"Даны различные написания одного и того же слова, взятые с плакатов 1912, 1934 и 1962 года:\n1. СЪЕЗД\n2. СЪѢЗДЪ\n3. С’ЕЗД\nВ каком году был написан какой плакат?","choices":["1 — 1912, 2 — 1934, 3 — 1962","1 — 1962, 2 — 1912, 3 — 1934","1 — 1934, 2 — 1962, 3 — 1912","1 — 1962, 2 — 1934, 3 — 1912","1 — 1934, 2 — 1912, 3 — 1962."],"key":"Б","review":["Съезд на трёх плакатах","В 1912 году ещё употреблялись ѣ и конечный ъ после твёрдого согласного: «СЪѢЗДЪ».","После реформы в первые десятилетия широко использовали апостроф: «С’ЕЗД» относится к 1934 году. Современное «СЪЕЗД» соответствует 1962 году."]},{"author":"О. Шеманаева","question":"Какое из этих слов может быть вводным словом?","choices":["<em>налево</em>","<em>прямо</em>","<em>напротив</em>","<em>направо</em>","<em>сзади</em>."],"key":"В","review":["Напротив, всё вышло","Вводное слово может обозначать связь между предложениями. Например: «Он не отказался. Напротив, он вызвался помочь».","Здесь «напротив» подчёркивает противопоставление. Слова «налево», «прямо», «направо» и «сзади» указывают направление или место."]},{"author":"П. Аркадьев","question":"Перед вами — отрывок из книги Льва Кассиля «Дело вкуса»: «<em>Ещё находятся у нас молодые люди, которые, ничтоже сумняшеся, позволяют себе сидеть, когда женщина стоит</em>». Что означает выражение <em>ничтоже сумняшеся</em>?","choices":["‘ничего не боясь’","‘ничуть не сомневаясь’","‘ничего не сумев’","‘ничем не интересуясь’","‘никого не спросив’."],"key":"Б","review":["Без малейших сомнений","В старинном обороте «ничтоже» означает «ничуть», а «сумняшеся» связано с глаголом «сомневаться».","Молодые люди позволяют себе сидеть совершенно спокойно, «ничуть не сомневаясь». Именно это передаёт оборот."]},{"author":"К. Кноп и И. Рубанов","question":"Саша написал: «<em>Мы будем рассматривать и лудшие, и хутшие варианты</em>». А как надо было написать?","choices":["так и надо было","<em>мы будем рассматривать и лутшие, и худшие варианты</em>","<em>мы будем рассматривать и лучшие, и хучшие варианты</em>","<em>мы будем рассматривать и лудшие, и худшие варианты</em>","<em>мы будем рассматривать и лучшие, и худшие варианты</em>."],"key":"Д","review":["Лучшие и худшие","Нужны словарные формы «лучший» и «худший». Перед ш пишутся разные согласные: ч и д.","Правильная фраза: «Мы будем рассматривать и лучшие, и худшие варианты»."]},{"author":"А. Бердичевский","question":"Что означает слово <em>одорант</em>?","choices":["‘обожатель, влюбленный’","‘поэт, пишущий оды’","‘тонкий аромат’","‘тот, кто обдирает шкуру с павших лошадей’","‘вещество, используемое для придания чему-либо запаха’."],"key":"Д","review":["Зачем нужен одорант","Слово связано с запахом. Одорант используют, чтобы у вещества появился характерный или заметный запах.","Например, к бытовому газу добавляют пахучее вещество, чтобы можно было вовремя заметить утечку."]},{"author":"И. Иткин и А. Снятковский","question":"В книге Святослава Рыбаса «Зеркало для героя» один малограмотный персонаж, желая блеснуть знанием фразеологии, с восхищением говорит другому: «<em>Вы храните свой авторитет, как...</em>»","choices":["<em>синица окуня</em>","<em>орёл карася</em>","<em>воробей акулу</em>","<em>соловей сома</em>","<em>утка карпа</em>."],"key":"А","review":["Зеница ока","В устойчивом выражении «беречь как зеницу ока» зеницей называется зрачок, а оком — глаз. Персонаж хочет таким же оборотом подчеркнуть, как бережно собеседник хранит авторитет.","Из вариантов звучание «зеницу ока» смешно переиначивает «синица окуня». Герой подменяет незнакомые ему слова знакомыми."]},{"author":"И. Иткин","question":"Какое из приведённых слов можно понять и как глагол совершенного, и как глагол несовершенного вида?","choices":["<em>настоять</em>","<em>отстоять</em>","<em>принадлежать</em>","<em>шествовать</em>","никакой."],"key":"Б","review":["Два значения «отстоять»","«Отстоять очередь» или «отстоять свою правоту» отвечает на вопрос «что сделать?». Это совершенный вид.","«Дом отстоит от берега на три километра» означает «находится на расстоянии». «Отстоять» в этом значении отвечает на вопрос «что делать?» и относится к несовершенному виду."]},{"author":"Е. Ренковская","question":"Даны турецкие слова и их переводы на русский: kapkara — <em>очень чёрный</em>, kolay — <em>лёгкий</em>, dapdar — <em>очень узкий</em>, kara — <em>чёрный</em>, sipsivri — <em>очень острый</em>. Переведите на турецкий: <em>узкий, очень лёгкий, острый</em>.","choices":["dap, kapkolay, sivri","dar, kopkolay, sivri","dar, kopkolay, sipri","dar, kolkolay, sipri","dar, kapkolay, sivri."],"key":"Б","review":["Усиление в турецком","Из «dapdar» и «sipsivri» уберём начальные усилительные части «dap-» и «sip-». Получим «dar» — «узкий» и «sivri» — «острый».","В примерах усиление начинается с начальных согласной и гласной исходного слова и заканчивается p. Для «kolay» это «kop-»: «kopkolay» — «очень лёгкий»."]},{"author":"Н. Валеева","question":"В какой из этих пословиц пропущено название не того животного, что в остальных?","choices":["<em>Страшнее … зверя нет</em>.","<em>Знает …, чьё мясо съела</em>.","<em>Ночью все … серы</em>.","<em>Доброе слово и … приятно</em>.","<em>Кот из дома — … в пляс</em>."],"key":"Д","review":["Кот и мыши","В первых четырёх пословицах пропущено слово «кошка» в нужной форме: страшнее кошки, знает кошка, все кошки серы, кошке приятно.","Последняя пословица звучит так: «Кот из дома — мыши в пляс». В этом пропуске нужны мыши."]},{"author":"И. Иткин","question":"Перед вами — отрывок из стихотворения Н. А. Некрасова «Поэт и гражданин» в том виде, как оно печатается в большинстве изданий:\n<em>Ему нет горше укоризны...\nИди в огонь за честь отчизны,\nЗа убежденье, за любовь...\nИди и гибни безупречно.\nУмрешь не даром... Дело прочно,\nКогда под ним струится кровь.</em>\nВ одной из строк этого отрывка есть отступление от норм произношения современного русского языка. В какой?","choices":["в первой","во второй","в третьей","в четвёртой","в пятой."],"key":"Г","review":["Старинная рифма Некрасова","Четвёртая строка «Иди и гибни безупречно» рифмуется с пятой, которая заканчивается словом «прочно». В рифме ударные гласные должны звучать одинаково.","Рифма показывает старое произношение «безупрёчно», с ударным о. Сейчас говорят «безупре́чно», поэтому искомая строка — четвёртая."]},{"author":"И. Иткин","question":"Расследуя запутанное дело, четыре знаменитых сыщика нашли оборванный слева и справа документ, на котором смогли прочитать только: «<em>...ять меч...</em>».\nРазгорелся спор: к какой части речи относилось слово, от которого остались буквы <em>...ять</em>.\n— Это мог быть глагол, — сказал Эркюль Пуаро.\n— Это могло быть числительное, — сказал комиссар Мегрэ.\n— Это могло быть наречие, — сказал отец Браун.\n— Это могло быть существительное, — сказал Шерлок Холмс.\nКто из них точно ошибся?","choices":["Пуаро","Мегрэ","отец Браун","Холмс","никто."],"key":"Д","review":["Улики в обрывке","Подходят глагол «взять меч» и числительное «пять мечей». В обоих примерах на обрывке осталось бы «...ять меч...».","Подходят также наречие «опять» в «опять мечтает» и существительное «память» в «память мечтателя». Ошибку ни одного сыщика из обрывка установить нельзя."]},{"author":"А. Бердичевский","question":"Какой звук не может обозначаться в русском языке буквой <em>г</em>: [г], [к], [в]?","choices":["[к]","[в]","[г] и [в]","[к] и [в]","все перечисленные могут."],"key":"Д","review":["Три звука одной буквы","В «гора» буква г обозначает [г]. На конце слова «снег» она оглушается и обозначает [к].","В «его» по традиции пишут г, а произносят [в]. В подходящих словах г передаёт каждый из трёх звуков."]},{"author":"Л. Фёдорова","question":"Какое из слов не имеет с остальными общего корня?","choices":["<em>спереди</em>","<em>предок</em>","<em>предтеча</em>","<em>прежде</em>","<em>впредь</em>."],"key":"В","review":["Перед и предтеча","«Спереди», «предок», «прежде» и «впредь» исторически связаны с корнем слова «перед».","В «предтече» пред- — приставка, а «теч» — корень, связанный с глаголом «течь». Предтечей называют того, кто появился раньше и предвосхитил последующие события."]},{"author":"К. Кноп","question":"В какой лаборатории Академии наук СССР был создан синтетический материал лавсан?","choices":["текстильных исследований","органических волокон","высокомолекулярных соединений","синтетических тканей","женских прихотей."],"key":"В","review":["Откуда название «лавсан»","«Лавсан» образован из частей названия лаборатории. «Ла» взято из слова «лаборатория», «АН» — начальные буквы «Академии наук».","Между ними остаются В и С: «высокомолекулярных соединений». В этой лаборатории Академии наук СССР и был получен материал."]},{"author":"Е. Муравенко","question":"Даны формы множественного числа существительных: 1) <em>деревья</em>, 2) <em>селенья</em>, 3) <em>коренья</em>, 4) <em>листья</em>. Какие из них образованы не от той основы, что формы единственного числа тех же слов?","choices":["только 1","только 2","только 1, 4","все, кроме 3","все, кроме 2."],"key":"Д","review":["Основа во множественном числе","У слова «селенье» звук [й] перед окончанием есть уже в единственном числе: селень[й]-е и селень[й]-а. Основа сохраняется.","В парах «дерево — деревья», «корень — коренья», «лист — листья» звук [й] появляется перед окончанием лишь во множественном числе. Меняется основа в примерах 1, 3 и 4."]}], {"year":2006,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2006.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
